  tenant_id: string;
  region: string;
  timestamp: string;
  governance_event_type: 'policy_update' | 'quota_violation' | 'model_swap' | 'audit';
  model_id: string;
  policy_version: string;
  user_id_hash: string;
  latency_ms: number;
  action_taken: string;
